  const table = LOOT_TABLES[tableId];
  const entries = Array.isArray(table?.entries) ? table.entries : [];
  const ids = new Set();
  for (const entry of entries) {
    if (entry?.type === "item" && typeof entry.itemId === "string") ids.add(entry.itemId);
